<!-- 文件职责 / File responsibility: 直接编辑每个可见材质的独立颜色通道。 / Directly edits every visible material's independent color channel. -->
<script setup lang="ts">
import {createDefaultPetCustomization,type PetPartColorRecipe} from '~/domain/pet-part-customization';import {usePetAppearanceStore} from '~/stores/pet-appearance';const store=usePetAppearanceStore();const groups:Array<{title:string;description:string;items:Array<[keyof PetPartColorRecipe,string,string]>}>=[{title:'身体与四肢',description:'身体、四肢、爪部和肚皮分别着色。',items:[['body','身体主体 / 尾根','Body / Tail Root'],['limbs','四肢 / 尾中段','Limbs / Mid Tail'],['paws','爪部 / 尾尖暖色','Paws / Warm Tail Tip'],['belly','肚皮','Belly Patch']]},{title:'脸部',description:'口鼻部、鼻子、嘴巴、舌头、脸颊、眼睛和高光均独立。',items:[['muzzle','口鼻部毛色','Muzzle'],['nose','鼻子','Nose'],['mouth','嘴部','Mouth'],['tongue','舌头','Tongue'],['cheeks','脸颊','Cheeks'],['eyes','眼睛','Eyes'],['eyeHighlight','眼睛高光','Eye Highlight']]},{title:'耳朵与触角',description:'外耳、内耳、耳尖、触角杆和触角尖均独立。',items:[['earOuter','外耳','Outer Ear'],['earInner','内耳','Inner Ear'],['earTip','耳尖','Ear Tip'],['antennaRod','触角杆','Antenna Rod'],['antennaTip','触角尖','Antenna Tip']]},{title:'能量与尾部',description:'尾尖发光与能量核心保持独立颜色。',items:[['tailGlow','尾尖发光','Tail Glow'],['energyCore','能量核心','Energy Core']]}];function update(key:keyof PetPartColorRecipe,e:Event){store.checkpoint();const value=(e.target as HTMLInputElement).value;store.recipe.customization.colors[key]=value;if(key==='body')store.recipe.palette.coatShadow=value;if(key==='limbs')store.recipe.palette.coat=value;if(key==='paws')store.recipe.palette.coatWarm=value;if(key==='eyes')store.recipe.palette.eye=value;if(key==='earOuter')store.recipe.earDesign.outerColor=value;if(key==='earInner')store.recipe.earDesign.innerColor=value;if(key==='earTip')store.recipe.earDesign.tipColor=value;if(key==='antennaTip')store.recipe.palette.antennaGlow=value;if(key==='tailGlow')store.recipe.tailDesign.tipGlow.color=value;store.markDirty()}function reset(){store.checkpoint();Object.assign(store.recipe.customization.colors,createDefaultPetCustomization(store.recipe).colors);store.markDirty()}
</script>
<template><section class="editor"><header><div><small>PART COLORS</small><h2>所有部位颜色</h2><p>每个可见材质通道独立保存并同步。</p></div><button @click="reset">恢复经典配色</button></header><section v-for="group in groups" :key="group.title" class="group"><h3>{{group.title}}</h3><p>{{group.description}}</p><div class="grid"><label v-for="[key,label,labelEn] in group.items" :key="key"><input type="color" :value="store.recipe.customization.colors[key]" @input="update(key,$event)"><span><strong>{{label}}</strong><small>{{labelEn}} · {{store.recipe.customization.colors[key]}}</small></span></label></div></section><section class="group"><h3>轨道与标志</h3><div class="grid"><label><input v-model="store.recipe.orbitDesign.primaryColor" type="color" @focus="store.checkpoint" @input="store.markDirty"><span><strong>主轨道</strong></span></label><label><input v-model="store.recipe.orbitDesign.secondaryColor" type="color" @focus="store.checkpoint" @input="store.markDirty"><span><strong>副轨道</strong></span></label><label><input v-model="store.recipe.symbols.chest.color" type="color" @focus="store.checkpoint" @input="store.markDirty"><span><strong>胸口标志</strong></span></label><label><input v-model="store.recipe.symbols.back.color" type="color" @focus="store.checkpoint" @input="store.markDirty"><span><strong>后背标志</strong></span></label></div></section></section></template>
<style scoped>.editor{display:grid;gap:12px}.editor>header,.group{padding:13px;border:1px solid #ffffff18;border-radius:15px;background:#0d1222}header{display:flex;justify-content:space-between}header small{color:#777f9f;font:800 8px ui-monospace}h2,h3,p{margin:0}p{margin-top:4px;color:#8f99b8;font-size:10px}button{border:1px solid #ffffff20;border-radius:8px;color:#fff;background:#ffffff08}.group{display:grid;gap:9px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.grid label{display:flex;align-items:center;gap:8px;padding:7px;border:1px solid #ffffff13;border-radius:9px;background:#080d1a}.grid input{width:38px;height:34px;border:0;background:transparent}.grid span{display:grid}.grid strong{font-size:10px}.grid small{color:#7f89a9;font-size:8px}</style>
